pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public { 
        c = new C();
        initialOwner = c.owner();
    }

    function testFuzz_property(address newOwner) public {
        // Only test with non-zero addresses for transferOwnership (reverts on zero? Actually onlyOwner requires caller is owner, not zero check)
        vm.assume(newOwner != address(0));

        // Record owner before
        address ownerBefore = c.owner();

        // If sender is owner, call transferOwnership (but since ownerBefore is known, we can prank as ownerBefore)
        vm.prank(ownerBefore);
        // We call transferOwnership to change the owner, then call owned()
        c.transferOwnership(newOwner);

        // Now call owned() 
        c.owned();

        // After owned(), owner should still be newOwner (since owned doesn't change owner)
        address finalOwner = c.owner();

        // The rule: finalOwner must equal newOwner (the owner after transferOwnership)
        assertTrue(finalOwner == newOwner);
    }
}

