pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. Restrict: caller is not the owner, and not the zero address (to avoid trivial cases)
        vm.assume(caller != address(0));
        address currentOwner = c.owner();
        vm.assume(caller != currentOwner);

        // 2. Drive: call owned() from a non-owner
        // Record owner before
        address ownerBefore = c.owner();
        // Call owned() as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // 3. Assert: owner unchanged
        assertTrue(c.owner() == ownerBefore);
    }
}

