pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // The reference C's transferOwnership only works when caller == owner
        // We need to ensure the rule holds for any caller.
        // Set owner to a known address to make the test deterministic.
        vm.assume(caller != address(0)); // avoid zero address for simplicity
        c.transferOwnership(address(1)); // set owner to some fixed address
        address originalOwner = c.owner();
        // Now call owned() as any caller
        vm.prank(caller);
        c.owned();
        // After owned(), the owner must remain unchanged (no-op for any caller)
        assertTrue(c.owner() == originalOwner);
    }
}

