// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;
    function setUp() public { c = new C(); initialOwner = address(this); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // 1. warp / prank to simulate arbitrary caller
        vm.prank(caller);
        // 2. call owned() — it only reverts if caller is not owner, but we must handle it
        bool ok;
        if (caller == initialOwner) {
            c.owned();
            ok = true;
        } else {
            (bool success,) = address(c).call(abi.encodeWithSignature("owned()"));
            ok = success;
        }
        // 3. The rule: the owner state variable never changes.
        assertTrue(c.owner() == initialOwner);
    }
}

